    char *buf = malloc(cap);
    if (buf == NULL) {
        return -1;
    }

    for (;;) {
        if (len == cap) {
            size_t new_cap = cap * 2;
            char *tmp = realloc(buf, new_cap);
            if (tmp == NULL) {
                free(buf);
                return -1;
            }
            buf = tmp;
            cap = new_cap;
        }

        size_t got = fread(buf + len, 1, cap - len, stdin);
        len += got;
        if (got == 0) {
