#include <stdio.h>

int main(void)
{
    int value;

    if (scanf("%d", &value) != 1) {
        return 1;
    }

    printf("%x\n", (unsigned int)value);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

static char *read_line(FILE *stream)
{
    size_t capacity = 0;
    size_t length = 0;
    char *buffer = NULL;
    int c;

    for (;;) {
        c = fgetc(stream);
        if (c == EOF) {
            break;
        }

        if (length + 2 > capacity) {
            size_t new_capacity = capacity == 0 ? 64 : capacity * 2;
            char *tmp = realloc(buffer, new_capacity);
            if (tmp == NULL) {
                free(buffer);
                return NULL;
            }
            buffer = tmp;
            capacity = new_capacity;
        }

        buffer[length++] = (char)c;
        if (c == '\n') {
            break;
        }
    }

    if (buffer == NULL) {
        return NULL;
    }

    buffer[length] = '\0';
    return buffer;
}

int main(void)
{
    char *line = read_line(stdin);
    if (line == NULL) {
        return 0;
    }

    for (char *p = line; *p != '\0'; ++p) {
        unsigned char ch = (unsigned char)*p;
        if (ch >= 'a' && ch <= 'z') {
            *p = (char)(ch - ('a' - 'A'));
        }
    }

    fputs(line, stdout);
    free(line);
    return 0;
}

