#include <stdio.h>
#include <stdlib.h>

static void sift_down(int *a, size_t n, size_t i)
{
    while (2 * i + 1 < n) {
        size_t child = 2 * i + 1;
        if (child + 1 < n && a[child + 1] > a[child]) {
            ++child;
        }
        if (a[i] >= a[child]) {
            break;
        }
        int tmp = a[i];
        a[i] = a[child];
        a[child] = tmp;
        i = child;
    }
}

static void heap_sort(int *a, size_t n)
{
    if (n < 2) {
        return;
    }

    for (size_t i = n / 2; i > 0; ) {
        --i;
        sift_down(a, n, i);
    }

    for (size_t end = n; end > 1; ) {
        --end;
        int tmp = a[0];
        a[0] = a[end];
        a[end] = tmp;
        sift_down(a, end, 0);
    }
}

