#include <stdio.h>
#include <stdlib.h>

static void swap(int *a, int *b) { int t = *a; *a = *b; *b = t; }

static int partition(int *a, int l, int r) {
    int m = (l + r) / 2;
    swap(&a[m], &a[r]);
    int p = a[r], i = l - 1;
    for (int j = l; j < r; j++)
        if (a[j] <= p) { i++; swap(&a[i], &a[j]); }
    swap(&a[i + 1], &a[r]);
    return i + 1;
}

static void qs(int *a, int l, int r) {
    if (l < r) {
        int q = partition(a, l, r);
        qs(a, l, q - 1);
        qs(a, q + 1, r);
    }
}

