#include <stdio.h>
#include <stdlib.h>

static void merge(int *a, int *t, int l, int m, int r) {
    int i = l, j = m + 1, k = l;
    while (i <= m && j <= r) {
        if (a[i] <= a[j]) t[k++] = a[i++];
        else t[k++] = a[j++];
    }
    while (i <= m) t[k++] = a[i++];
    while (j <= r) t[k++] = a[j++];
    for (i = l; i <= r; i++) a[i] = t[i];
}

static void sort(int *a, int *t, int l, int r) {
    if (l >= r) return;
    int m = l + (r - l) / 2;
    sort(a, t, l, m);
    sort(a, t, m + 1, r);
    merge(a, t, l, m, r);
}

