#include <stdio.h>
#include <stdlib.h>

void sift_down(int *a, int start, int end) {
    int root = start;
    while (root * 2 + 1 <= end) {
        int child = root * 2 + 1;
        if (child + 1 <= end && a[child] < a[child + 1]) child++;
        if (a[root] < a[child]) {
            int t = a[root];
            a[root] = a[child];
            a[child] = t;
            root = child;
        } else {
            break;
        }
    }
}

int main(void) {
