static long long gcd(long long a, long long b) {
    /* Work with non-negative values so modulo is well-behaved. */
    if (a < 0) a = -a;
    if (b < 0) b = -b;

    while (b != 0) {
        long long remainder = a % b;
        a = b;
        b = remainder;
    }

    /* If both inputs are zero, this correctly returns 0. */
    return a;
}

