#include <stdio.h>
#include <stdlib.h>

int main(void) {
    size_t cap = 128;
    size_t len = 0;
    char *line = malloc(cap);
    if (line == NULL) {
        return 1;
    }

    /* Read one line (until newline or EOF), growing the buffer as needed. */
    int c;
    while ((c = getchar()) != EOF && c != '\n') {
        if (len + 1 >= cap) {
            size_t new_cap = cap * 2;
            char *tmp = realloc(line, new_cap);
            if (tmp == NULL) {
                free(line);
                return 1;
            }
            line = tmp;
            cap = new_cap;
        }
        line[len++] = (char)c;
    }
    line[len] = '\0';

    /* Compare from both ends, skipping spaces. */
    size_t left = 0;
    size_t right = len;
    int is_palindrome = 1;

    while (left < right) {
        while (left < right && line[left] == ' ') {
            left++;
        }
        while (left < right && line[right - 1] == ' ') {
            right--;
        }
        if (left >= right) {
            break;
        }
        if (line[left] != line[right - 1]) {
            is_palindrome = 0;
            break;
        }
        left++;
        right--;
    }

    printf("%d\n", is_palindrome);
    free(line);
    return 0;
}
